SELECT DATE_FORMAT(a.opened_date, 'yyyy-MM') opened_month, ROUND((100 * SUM(CASE WHEN t.merchant = 'Amazon' THEN 1 ELSE 0 END)) / COUNT(*), 1) pct_amazon FROM transactions t LEFT JOIN accounts a ON t.account_id = a.id WHERE a.account_type <> 'LOAN' GROUP BY DATE_FORMAT(a.opened_date, 'yyyy-MM') HAVING ROUND((100 * SUM(CASE WHEN t.merchant = 'Amazon' THEN 1 ELSE 0 END)) / COUNT(*), 1) > 43;
